/*
 * prog30_escape_unescape.c
 *
 * Re‑implementation of the original program whose behaviour was observed
 * in the supplied binary.  The program accepts two command‑line arguments:
 *
 *   prog30_escape_unescape <mode> <string>
 *
 *   <mode>   – either "escape" or "unescape"
 *   <string> – the text to be processed (maximum length 1023 bytes)
 *
 * Behaviour
 * ----------
 *   * If fewer than three arguments are supplied the program prints
 *     "USAGE" and exits with status 0.
 *
 *   * If the mode is not exactly "escape" or "unescape" the program prints
 *     "INVALID_MODE" and exits with status 0.
 *
 *   * If the input string is longer than 1023 characters the program prints
 *     "INVALID" and exits with status 0.
 *
 *   * Otherwise the program processes the string and prints the result
 *     (followed by a newline, as `puts` does).
 *
 *   * In **escape** mode the following characters are replaced by the
 *     corresponding C‑style escape sequences:
 *
 *           '\\'  →  "\\\\"
 *           '\n'  →  "\\n"
 *           '\t'  →  "\\t"
 *           '\"'  →  "\\\""
 *
 *     All other characters are copied unchanged.
 *
 *   * In **unescape** mode the reverse transformation is performed:
 *
 *           "\\\\" → '\\'
 *           "\\n"  → '\n'
 *           "\\t"  → '\t'
 *           "\\\"" → '\"'
 *
 *     If a backslash is the last character of the input, it is copied
 *     verbatim.  For any other backslash that is **not** followed by one of
 *     the four recognised characters, the backslash is discarded and only
 *     the following character is copied (this matches the behaviour observed
 *     in the original binary).
 *
 * The implementation below follows the logic discovered in the decompiled
 * binary while using normal, readable C code.
 */

#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_INPUT 1023                 /* limit observed in the original binary */
#define OUT_BUF   (2 * MAX_INPUT + 1)  /* worst case: every input char becomes two */

static void escape_string(const char *in, char *out)
{
    while (*in) {
        unsigned char c = (unsigned char)*in++;
        switch (c) {
            case '\\':
                *out++ = '\\';
                *out++ = '\\';
                break;
            case '\n':
                *out++ = '\\';
                *out++ = 'n';
                break;
            case '\t':
                *out++ = '\\';
                *out++ = 't';
                break;
            case '"':
                *out++ = '\\';
                *out++ = '"';
                break;
            default:
                *out++ = c;
                break;
        }
    }
    *out = '\0';
}

/* Unescape according to the exact behaviour of the original binary:
 *   - recognised escapes are translated;
 *   - an isolated backslash at the end is copied;
 *   - an unrecognised escape discards the backslash and copies only the
 *     following character. */
static void unescape_string(const char *in, char *out)
{
    while (*in) {
        if (*in == '\\') {
            /* Look ahead – if there is no following character, copy the backslash */
            if (in[1] == '\0') {
                *out++ = '\\';
                ++in;               /* consume the backslash */
                continue;
            }
            switch (in[1]) {
                case '\\':
                    *out++ = '\\';
                    in += 2;
                    break;
                case 'n':
                    *out++ = '\n';
                    in += 2;
                    break;
                case 't':
                    *out++ = '\t';
                    in += 2;
                    break;
                case '"':
                    *out++ = '"';
                    in += 2;
                    break;
                default:
                    /* Unrecognised escape – drop the backslash, copy the next char */
                    *out++ = in[1];
                    in += 2;
                    break;
            }
        } else {
            *out++ = *in++;
        }
    }
    *out = '\0';
}

int main(int argc, char *argv[])
{
    /* The original binary printed "USAGE" when argc < 3 */
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    const char *mode  = argv[1];
    const char *input = argv[2];

    /* Mode validation */
    if (strcmp(mode, "escape") != 0 && strcmp(mode, "unescape") != 0) {
        puts("INVALID_MODE");
        return 0;
    }

    /* Input length validation – the original code rejected >0x3ff bytes */
    if (strlen(input) > MAX_INPUT) {
        puts("INVALID");
        return 0;
    }

    /* Allocate a buffer large enough for the worst‑case output */
    char *outbuf = malloc(OUT_BUF);
    if (!outbuf) {
        perror("malloc");
        return 1;
    }

    if (strcmp(mode, "escape") == 0) {
        escape_string(input, outbuf);
    } else {
        unescape_string(input, outbuf);
    }

    puts(outbuf);
    free(outbuf);
    return 0;
}
